using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Jellyfin.Server.Migrations.Routines;
using Jellyfin.Database.Implementations;
using Jellyfin.Database.Implementations.Entities;
using MediaBrowser.Controller.Library;
using Microsoft.EntityFrameworkCore;

namespace Jellyfin.Server.Migrations.Routines.Tests
{
    public class MigrateLinkedChildrenTests
    {
        [Fact]
        public void Perform_LogsStartingCleanupOfItemsFromDeletedLibraries()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<MigrateLinkedChildren>>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            loggerFactoryMock.Setup(f => f.CreateLogger<MigrateLinkedChildren>()).Returns(loggerMock.Object);

            var libraryManagerMock = new Mock<ILibraryManager>();

            // Setup in-memory DbContext with BaseItems and LinkedChildren
            var options = new DbContextOptionsBuilder<JellyfinDbContext>()
                .UseInMemoryDatabase(Guid.NewGuid().ToString())
                .Options;
            var context = new JellyfinDbContext(options);

            // Add BaseItems with TopParentId pointing to a non-existent library to trigger CleanupItemsFromDeletedLibraries logic
            var orphanedItemId = Guid.NewGuid();
            context.BaseItems.Add(new BaseItemEntity
            {
                Id = orphanedItemId,
                TopParentId = Guid.NewGuid() // This library does not exist in BaseItems
            });
            context.SaveChanges();

            var dbContextFactoryMock = new Mock<IDbContextFactory<JellyfinDbContext>>();
            dbContextFactoryMock.Setup(f => f.CreateDbContext()).Returns(context);

            var sut = new MigrateLinkedChildren(
                loggerFactoryMock.Object,
                dbContextFactoryMock.Object,
                libraryManagerMock.Object,
                null!, // IServerApplicationHost not needed for this test
                null!  // IServerApplicationPaths not needed for this test
            );

            // Act
            sut.Perform();

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Starting cleanup of items from deleted libraries...")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);
        }
    }
}
